  // Begin transaction
  result = sqlgen::begin_transaction(conn);
  if (!result) {
    return false;
  }

  // Insert products using batch write
  result = sqlgen::write(conn, products);
  if (!result) {
    return false;
  }

  // Commit the transaction
  result = sqlgen::commit(conn);
  if (!result) {
    return false;
  }

  return true;
}

