    using namespace sqlgen;

    // 1. Connect to the SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // 2. Create User and Post tables
    conn->execute(create_table<User>);
    conn->execute(create_table<Post>);

    // 3. Find users who have created at least one post between 2025-12-01 and 2025-12-31
    // Using the SQL pattern: SELECT DISTINCT u.user_id, u.username
    // FROM User u
    // INNER JOIN Post p ON u.user_id = p.user_id
    // WHERE p.created_at >= DATE('2025-12-01') AND p.created_at <= DATE('2025-12-31')

    using namespace sqlgen::literals;

    auto query = select_from<User, "u">("user_id"_c, "username"_c)
        | join<Post, "p">("u"_c / "user_id"_c == "p"_c / "user_id"_c)
        | where(
            ("p"_c / "created_at"_c >= sqlgen::val(std::string("2025-12-01"))) &&
            ("p"_c / "created_at"_c <= sqlgen::val(std::string("2025-12-31")))
          )
        | to<ActiveUser>;

