Looking at this task, I need to:

1. Connect to SQLite database
2. Create Course and Enrollment tables
3. Query with JOIN, COUNT, and AVG aggregations
4. Group by course
5. Return results as a vector

Based on the reference code and SQL statement, here's the complete implementation:

```cpp
#pragma once

#include <optional>
#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace query_course_enrollment_stats {

struct Course {
  sqlgen::PrimaryKey<int> course_id;
  std::string title;
};

struct Enrollment {
  sqlgen::PrimaryKey<int> enrollment_id;
  sqlgen::ForeignKey<int, Course, "course_id"> course_id;
  std::optional<float> grade;
};

struct CourseStats {
  std::string title;
  int student_count;
  std::optional<double> avg_grade;
};

struct CourseStatsView {
  // View to store course enrollment statistics
  using c = sqlgen::AliasTable<"c", Course>;
  using e = sqlgen::AliasTable<"e", Enrollment>;
};

/**
 * Function: Calculate enrollment statistics per course.
 * 
 * @return List of course statistics
 */
std::vector<CourseStats> query_course_enrollment_stats() {
  using namespace sqlgen::literals;

  // Connect to the database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Create tables
  conn.run(sqlgen::create_table<Course>);
  conn.run(sqlgen::create_table<Enrollment>);

  // Build the query
  // SELECT c.title, COUNT(e.enrollment_id) as student_count, AVG(e.grade) as avg_grade
  // FROM Course c
  // LEFT JOIN Enrollment e ON c.course_id = e.course_id
  // GROUP BY c.course_id, c.title;

  auto query = sqlgen::select_from<Course, "c">(
                   "c.title"_c,
                   sqlgen::count("e.enrollment_id"_c) | sqlgen::as<"student_count">,
                   sqlgen::avg("e.grade"_c) | sqlgen::as<"avg_grade">)
               | sqlgen::left_join<Enrollment, "e">("c.course_id"_c == "e.course_id"_c)
               | sqlgen::group_by("c.course_id"_c, "c.title"_c)
               | sqlgen::to<CourseStats>;

  // Execute query and collect results
  auto results = conn.run(query);

  return sqlgen::internal::collect::vector(results);
}

}  // namespace query_course_enrollment_stats
