  sqlgen::PrimaryKey<int> visit_id;
  std::string url;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> visit_time;
};

struct DailyTraffic {
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

struct DailyTrafficView {
  static constexpr const char* tablename = "DailyTrafficView";
  static constexpr bool is_view = true;
  std::string visit_date;
  int total_visits;
  int unique_pages;
};

/**
 * Function: Calculate daily traffic metrics from a log table.
 * 
 * @return List of daily traffic metrics
 */
std::vector<DailyTraffic> query_daily_traffic_metrics() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto db = sqlite::connect("test_db.sqlite");

  // Create column references using user-defined literals
  using namespace sqlgen::literals;
  auto visit_date_col = "visit_date"_c;
  auto total_visits_col = "total_visits"_c;
  auto unique_pages_col = "unique_pages"_c;

  // Build the query: extract date, count total visits and unique URLs
  auto query = select_from<PageVisit>(
    strftime<"%Y-%m-%d">("visit_time"_c) | as<"visit_date">,
    count() | as<"total_visits">,
    count_distinct("url"_c) | as<"unique_pages">
  )
  | group_by(visit_date_col)
  | order_by(visit_date_col)
  | to<DailyTraffic>;

  // Execute the query and return results
  return db.run(query);
}

}  // namespace query_daily_traffic_metrics
```

