Looking at the requirements and the reference code, I need to implement a function that:
1. Connects to SQLite database "test_db.sqlite"
2. Performs an INNER JOIN between Order and Customer tables
3. Filters orders with total_amount > 1000
4. Orders results by total_amount descending
5. Returns a list of OrderView results

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>
#include <vector>

namespace query_high_value_orders {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct OrderView {
  static constexpr const char* tablename = "HighValueOrderView";
  static constexpr bool is_view = true;
  sqlgen::PrimaryKey<int> order_id;
  std::string name;
  double total_amount;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

std::vector<OrderView> query_high_value_orders() {
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");

  // Build the query:
  // SELECT o.order_id, c.name, o.total_amount, o.order_date
  // FROM "Order" o
  // INNER JOIN Customer c ON o.customer_id = c.customer_id
  // WHERE o.total_amount > 1000
  // ORDER BY o.total_amount DESC;

  auto query = sqlgen::select_from<Order, "o">(
                   "order_id"_c,
                   "name"_c,
                   "total_amount"_c,
                   "order_date"_c
               )
               | sqlgen::inner_join<Customer, "c">(
                   "o.customer_id"_c == "c.customer_id"_c
               )
               | sqlgen::where("o.total_amount"_c > 1000.0)
               | sqlgen::order_by(sqlgen::desc("o.total_amount"_c))
               | sqlgen::to<OrderView>;

  // Execute the query and return results
  return conn->run(query);
}

}  // namespace query_high_value_orders
```

The implementation:
1. **Uses `sqlgen::sqlite::connect`** to connect to "test_db.sqlite"
2. **Builds the query using the fluent API**:
   - `select_from<Order, "o">()` - selects from Order table with alias "o"
   - `inner_join<Customer, "c">()` - performs INNER JOIN with Customer table aliased as "c"
   - `where()` - filters by total_amount > 1000
   - `order_by()` - orders by total_amount descending (using `desc()`)
   - `to<OrderView>` - maps results to OrderView structure
3. **Executes the query** with `conn->run(query)`
4. **Returns** the vector of OrderView results

