                 sum("s"_c / "amount"_c) | as<"total_amt">
               )
               | inner_join<Sale, "s">("p"_c / "product_id"_c == "s"_c / "product_id"_c)
               | group_by("p"_c / "category"_c)
               | where(sum("s"_c / "amount"_c) > 5000.0)
               | to<CategoryReport>;

