```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <iostream>
#include <exception>

namespace schema_migration_add_column {

struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct UserAfter {
  sqlgen::PrimaryKey<int, sqlgen::auto_incr> user_id;
  std::string username;
  std::string phone_number;
  bool is_active;
};

/**
 * Function: Perform schema migration to add new columns.
 * 
 * @return true if migration succeeds, false otherwise
 */
bool migration_add_column() {
  try {
    // Connect to the SQLite database
    auto conn = sqlgen::sqlite::connect("test_db.sqlite");

    // Prepare ALTER TABLE statements to add new columns
    std::string alter_phone_number = 
      "ALTER TABLE User ADD COLUMN phone_number VARCHAR(20)";

    // SQLite uses INTEGER for boolean, 1 for true
    std::string alter_is_active = 
      "ALTER TABLE User ADD COLUMN is_active INTEGER DEFAULT 1";

    try {
      // Execute the first ALTER TABLE statement to add phone_number
      conn->execute(alter_phone_number);
    } catch (const std::exception& e) {
      // Check if column already exists - this is acceptable
      std::string error_msg = e.what();
      if (error_msg.find("duplicate column name") == std::string::npos &&
          error_msg.find("already exists") == std::string::npos) {
        // If it's not a "column exists" error, rethrow
        std::cerr << "Error adding phone_number column: " << e.what() << std::endl;
        throw;
      }
      // Column already exists, continue
    }

    try {
      // Execute the second ALTER TABLE statement to add is_active
      conn->execute(alter_is_active);
    } catch (const std::exception& e) {
      // Check if column already exists - this is acceptable
      std::string error_msg = e.what();
      if (error_msg.find("duplicate column name") == std::string::npos &&
          error_msg.find("already exists") == std::string::npos) {
        // If it's not a "column exists" error, rethrow
        std::cerr << "Error adding is_active column: " << e.what() << std::endl;
        throw;
      }
      // Column already exists, continue
    }

    return true;

  } catch (const std::exception& e) {
    std::cerr << "Migration failed: " << e.what() << std::endl;
    return false;
  } catch (...) {
    std::cerr << "Migration failed: Unknown error" << std::endl;
    return false;
  }
}

} // namespace schema_migration_add_column
```

