```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace soft_delete_records {

struct Document {
  sqlgen::PrimaryKey<int> doc_id;
  std::string title;
  int is_deleted = 0;
  std::optional<sqlgen::DateTime> deleted_at;
};

bool soft_delete_records(const std::vector<int>& ids) {
    // Return true if no IDs to delete
    if (ids.empty()) {
        return true;
    }

    try {
        // Connect to the SQLite database
        auto conn = sqlgen::sqlite::connect("test_db.sqlite");

        // Use literals for column names
        using namespace sqlgen::literals;

        // Create the update statement
        // Set is_deleted = 1 and deleted_at = CURRENT_TIMESTAMP
        auto update_stmt = sqlgen::update<Document>(
            "is_deleted"_c = 1,
            "deleted_at"_c = sqlgen::DateTime::now()
        );

        // Apply WHERE clause with IN condition
        // For sqlgen, we need to iterate through the IDs and update them
        // Wrapping in a transaction for better performance
        conn->execute("BEGIN TRANSACTION");

        for (const auto& id : ids) {
            auto query = update_stmt | sqlgen::where("doc_id"_c == id);
            conn->execute(query);
        }

        conn->execute("COMMIT");

        return true;

    } catch (const std::exception& e) {
        // If any error occurs, return false
        return false;
    }
}

}  // namespace soft_delete_records
```

