int update_order_status() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  int total_affected = 0;

  // 1. Update pending orders older than 7 days to 'expired'
  // Using SQLite's DATE('now', '-7 days') function
  auto pending_update = update<Order>(
    "status"_c.set("expired")
  ) | where(
    "status"_c == "pending" && 
    "order_date"_c < sqlgen::RawSQL("DATE('now', '-7 days')")
  );

  auto result1 = pending_update(conn);
  total_affected += result1.rows_affected();

  // 2. Update shipped orders to 'delivered'
  // (simulating delivery confirmation received for all shipped orders)
  auto shipped_update = update<Order>(
    "status"_c.set("delivered")
  ) | where(
    "status"_c == "shipped"
  );

  auto result2 = shipped_update(conn);
  total_affected += result2.rows_affected();

  // Commit the changes
  commit(conn);

  return total_affected;
}

} // namespace update_order_status
