bool upsert_inventory_items(const std::vector<Inventory>& items) {
  // Connect to the SQLite database
  auto conn = sqlgen::sqlite::connect("test_db.sqlite");
  if (!conn) {
    return false;
  }

  // Perform upsert (insert or replace) operation
  auto write_result = sqlgen::write(conn, items);
  if (!write_result) {
    return false;
  }

  // Read back items to verify
  std::vector<Inventory> read_items;
  auto read_result = write_result.and_then(
      [&](const auto& _conn) { 
        return _conn->read(sqlgen::read<Inventory>, read_items); 
      });

  if (!read_result) {
    return false;
  }

  // Verify that the number of items matches
  if (read_items.size() != items.size()) {
    return false;
  }

  // Verify that all items were upserted correctly
  for (const auto& item : items) {
    bool found = false;
    for (const auto& read_item : read_items) {
      if (read_item.item_id.val == item.item_id.val &&
          read_item.name == item.name &&
          read_item.quantity == item.quantity) {
        found = true;
        break;
      }
    }
    if (!found) {
      return false;
    }
  }

  return true;
}

