struct User {
  sqlgen::PrimaryKey<int> user_id;
  std::string username;
};

struct Friendship {
  int user1_id;
  int user2_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> created_at;
};

struct FriendConnection {
  std::string user1_name;
  std::string user2_name;
};

/**
 * Analyze social network data by creating temporary SQL tables for User and Friendship.
 * Returns: std::vector<FriendConnection>.
 */
std::vector<FriendConnection> analyze_social_network_impl(const std::vector<User>& users, const std::vector<Friendship>& friendships) {
  // Create SQLite database connection
  sqlgen::sqlite::Database db("test_db.sqlite");

  // Create User table
  auto user_table = db.CreateTable<User>("User");

  // Create Friendship table
  auto friendship_table = db.CreateTable<Friendship>("Friendship");

  // Insert users into the database
  for (const auto& user : users) {
    user_table.Insert(user);
  }

  // Insert friendships into the database
  for (const auto& friendship : friendships) {
    friendship_table.Insert(friendship);
  }

  // Query 1: Find mutual friends using SELF-JOIN
  // This finds pairs of users who are friends and have at least one mutual friend
  auto mutual_friends_query = db.Query(R"(
    SELECT u1.username as user1_name, u2.username as user2_name, COUNT(DISTINCT f1.user2_id) as mutual_count
    FROM User u1
    INNER JOIN Friendship f1 ON u1.user_id = f1.user1_id
    INNER JOIN Friendship f2 ON f1.user2_id = f2.user1_id
    INNER JOIN User u2 ON f2.user2_id = u2.user_id
    WHERE u1.user_id < u2.user_id
      AND EXISTS (
        SELECT 1 FROM Friendship f3 
        WHERE f3.user1_id = u1.user_id AND f3.user2_id = u2.user_id
      )
    GROUP BY u1.user_id, u2.user_id, u1.username, u2.username
    HAVING COUNT(DISTINCT f1.user2_id) > 0
  )");

  // Query 2: Find users with above-average friend count (nested query)
  auto popular_users_query = db.Query(R"(
    SELECT u.user_id, u.username, COUNT(f.user2_id) as friend_count
    FROM User u
    LEFT JOIN Friendship f ON u.user_id = f.user1_id
    GROUP BY u.user_id, u.username
    HAVING friend_count > (
      SELECT AVG(friend_count) 
      FROM (SELECT COUNT(*) as friend_count FROM Friendship GROUP BY user1_id)
    )
    ORDER BY friend_count DESC
  )");

  // Query 3: Find friend-of-friend relationships (not direct friends)
  auto fof_query = db.Query(R"(
    SELECT DISTINCT u1.username as user1_name, u3.username as user2_name
    FROM User u1
    INNER JOIN Friendship f1 ON u1.user_id = f1.user1_id
    INNER JOIN Friendship f2 ON f1.user2_id = f2.user1_id
    INNER JOIN User u3 ON f2.user2_id = u3.user_id
    WHERE u1.user_id != u3.user_id
      AND NOT EXISTS (
        SELECT 1 FROM Friendship f3
        WHERE f3.user1_id = u1.user_id AND f3.user2_id = u3.user_id
      )
  )");

  // Query 4: Count friends per user and identify most connected users
  auto connection_stats_query = db.Query(R"(
    SELECT u.username, COUNT(f.user2_id) as friend_count
    FROM User u
    LEFT JOIN Friendship f ON u.user_id = f.user1_id
    GROUP BY u.user_id, u.username
    ORDER BY friend_count DESC
    LIMIT 10
  )");

  // Query 5: Find users in the same city who are not yet friends (recommendation)
  // Note: Since our User struct doesn't have a city field, we'll simulate this
  auto recommendation_query = db.Query(R"(
    SELECT DISTINCT u1.username as user1_name, u2.username as user2_name
    FROM User u1
    CROSS JOIN User u2
    WHERE u1.user_id < u2.user_id
      AND NOT EXISTS (
        SELECT 1 FROM Friendship f
        WHERE (f.user1_id = u1.user_id AND f.user2_id = u2.user_id)
           OR (f.user1_id = u2.user_id AND f.user2_id = u1.user_id)
      )
  )");

  // Execute queries and collect results
  std::vector<FriendConnection> results;

  // Process mutual friends results
  auto mutual_results = mutual_friends_query.Execute();
  for (const auto& row : mutual_results) {
    FriendConnection fc;
    fc.user1_name = row.Get<std::string>("user1_name");
    fc.user2_name = row.Get<std::string>("user2_name");
    results.push_back(fc);
  }

  // Process friend-of-friend results
  auto fof_results = fof_query.Execute();
  for (const auto& row : fof_results) {
    FriendConnection fc;
    fc.user1_name = row.Get<std::string>("user1_name");
    fc.user2_name = row.Get<std::string>("user2_name");
    results.push_back(fc);
  }

  return results;
}

}  // namespace analyze_social_network
```

