```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>
#include <optional>

namespace calculate_order_metrics {

struct OrderItem {
  sqlgen::PrimaryKey<int> item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  std::optional<double> discount_rate;
  std::optional<double> tax_rate;
};

struct OrderMetrics {
  int item_id;
  int order_id;
  int product_id;
  double unit_price;
  int quantity;
  double discount_rate;
  double tax_rate;
  double gross_total;
  double discounted_total;
  double final_total;
  double unit_cost;
  int quantity_group;
  double estimated_profit;
};

/**
 * Calculate per-item order metrics by loading the provided items into a temporary SQLite table
 * and evaluating SQL expressions for totals, discounts, taxes, cost, grouping, and estimated profit.
 * @param items Vector of OrderItem records to analyze.
 * @return std::vector<OrderMetrics> Analysis results for each order item.
 */
std::vector<OrderMetrics> calculate_order_metrics_impl(const std::vector<OrderItem>& items) {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Write the items to the database (creates table and inserts data)
  auto write_result = write(conn, items);

  if (!write_result) {
    return {};
  }

  // Define column accessors
  constexpr auto item_id = col<"item_id", OrderItem>;
  constexpr auto order_id = col<"order_id", OrderItem>;
  constexpr auto product_id = col<"product_id", OrderItem>;
  constexpr auto unit_price = col<"unit_price", OrderItem>;
  constexpr auto quantity = col<"quantity", OrderItem>;
  constexpr auto discount_rate = col<"discount_rate", OrderItem>;
  constexpr auto tax_rate = col<"tax_rate", OrderItem>;

  // Calculate metrics using arithmetic operations
  // gross_total = unit_price * quantity
  const auto gross_total = unit_price * quantity;

  // discounted_total = unit_price * quantity * (1 - COALESCE(discount_rate, 0)/100)
  const auto discounted_total = 
      unit_price * quantity * (1.0 - coalesce(discount_rate, 0.0) / 100.0);

  // final_total = discounted_total * (1 + COALESCE(tax_rate, 0)/100)
  const auto final_total = 
      unit_price * quantity * (1.0 - coalesce(discount_rate, 0.0) / 100.0) * 
      (1.0 + coalesce(tax_rate, 0.0) / 100.0);

  // unit_cost = unit_price * quantity / quantity (simplifies to unit_price)
  const auto unit_cost = unit_price * quantity / quantity;

  // quantity_group = quantity % 10
  const auto quantity_group = quantity % 10;

  // estimated_profit = unit_price * 0.3
  const auto estimated_profit = unit_price * 0.3;

  // Build and execute the query
  std::vector<OrderMetrics> results;

  auto query = 
      select(
          as<"item_id">(item_id),
          as<"order_id">(order_id),
          as<"product_id">(product_id),
          as<"unit_price">(unit_price),
          as<"quantity">(quantity),
          as<"discount_rate">(coalesce(discount_rate, 0.0)),
          as<"tax_rate">(coalesce(tax_rate, 0.0)),
          as<"gross_total">(gross_total),
          as<"discounted_total">(discounted_total),
          as<"final_total">(final_total),
          as<"unit_cost">(unit_cost),
          as<"quantity_group">(quantity_group),
          as<"estimated_profit">(estimated_profit)
      )
      .from<OrderItem>();

  auto read_result = conn.and_then([&](auto& connection) {
    return connection->execute(query, read<OrderMetrics>);
  });

  if (read_result) {
    results = std::move(read_result.value());
  }

  return results;
}

}  // namespace calculate_order_metrics
