Based on the reference code patterns, here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace join_orders_customers_payments {

struct Customer {
  sqlgen::PrimaryKey<int> customer_id;
  std::string name;
};

struct Order {
  sqlgen::PrimaryKey<int> order_id;
  int customer_id;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> order_date;
};

struct Payment {
  sqlgen::PrimaryKey<int> payment_id;
  int order_id;
  double amount;
};

struct Consolidated {
  sqlgen::PrimaryKey<int> order_id;
  std::string customer_name;
  double amount;
};

/**
 * description: join_orders_customers_payments.
 * This function demonstrates how to join three tables (Orders, Customers, and Payments)
 * and return a consolidated view with order_id, customer_name, and amount.
 * It orders the results by amount in descending order.
 * Returns: std::vector<Consolidated>.
 */
std::vector<Consolidated> join_orders_customers_payments() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Build the query with joins
  auto query = select_from<Order, "o">(
      "o"_c / "order_id"_c | as<"order_id">,
      "c"_c / "name"_c | as<"customer_name">,
      "p"_c / "amount"_c | as<"amount">
    )
    | inner_join<Customer, "c">("c"_c / "customer_id"_c == "o"_c / "customer_id"_c)
    | inner_join<Payment, "p">("p"_c / "order_id"_c == "o"_c / "order_id"_c)
    | order_by("p"_c / "amount"_c.desc())
    | to<Consolidated>;

  // Execute the query and collect results into a vector
  return internal::collect::vector(conn.select(query));
}

}  // namespace join_orders_customers_payments
```

