#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>

namespace update_set_operations {

struct Account {
  sqlgen::PrimaryKey<int> account_id;
  double balance;
  std::string status;
};

/**
 * description: update_set_operations.
 * This function demonstrates how to use set operations in update statements using sqlgen write API.
 * It returns true if the update operations are successful, and false otherwise.
 * Returns: bool.
 */
bool update_set_operations() {
  using namespace sqlgen;
  using namespace sqlgen::literals;

  try {
    // Connect to SQLite database
    auto conn = sqlite::connect("test_db.sqlite");

    // 1. Create Account table
    write(conn, create_table<Account>);

    // Insert some initial test data
    write(conn, insert_into<Account>({
      {.account_id = 1, .balance = 100.0, .status = "active"},
      {.account_id = 2, .balance = 200.0, .status = "active"},
      {.account_id = 3, .balance = 300.0, .status = "inactive"}
    }));

    // 2. Update balances and statuses using set(...)
    // Update account 1: set balance to 150.0
    write(conn, 
      update<Account>(
        "balance"_c.set(150.0)
      ) | where("account_id"_c == 1)
    );

    // Update account 2: set status to "suspended"
    write(conn, 
      update<Account>(
        "status"_c.set("suspended")
      ) | where("account_id"_c == 2)
    );

    // Update account 3: set both balance and status
    write(conn, 
      update<Account>(
        "balance"_c.set(350.0),
        "status"_c.set("active")
      ) | where("account_id"_c == 3)
    );

    // 3. Verify changes persisted
    auto results = read<Account>(conn, select_all<Account>);

    // Check if we have 3 accounts
    if (results.size() != 3) {
      return false;
    }

    // Verify account 1 changes
    bool account1_valid = false;
    bool account2_valid = false;
    bool account3_valid = false;

    for (const auto& account : results) {
      if (account.account_id() == 1) {
        account1_valid = (account.balance == 150.0 && account.status == "active");
      } else if (account.account_id() == 2) {
        account2_valid = (account.balance == 200.0 && account.status == "suspended");
      } else if (account.account_id() == 3) {
        account3_valid = (account.balance == 350.0 && account.status == "active");
      }
    }

    return account1_valid && account2_valid && account3_valid;

  } catch (...) {
    return false;
  }
}

}  // namespace update_set_operations

