Looking at the requirements and reference code, I need to:

1. Create a SQLite connection
2. Use `select_from` to query the Book table
3. Order by pages in descending order using `order_by` and `desc()`
4. Convert results to `std::vector<Book>` using `to<std::vector<Book>>`
5. Execute the query on the connection

Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace select_from_read_to_vector {

struct Book {
  sqlgen::PrimaryKey<int> book_id;
  std::string title;
  int pages;
};

/**
 * description: select_from_read_to_vector.
 * This function demonstrates how to read data from a table using sqlgen read API and store it in a vector.
 * It returns a vector of Book structs, where each struct contains the book_id, title, and pages.
 * Returns: std::vector<Book>, ordered by pages in descending order.
 */
std::vector<Book> select_from_read_to_vector() {
  using namespace sqlgen;

  // Create a SQLite connection
  auto conn = sqlite::connect(":memory:");

  // Create the books table
  conn->execute(
      "CREATE TABLE IF NOT EXISTS Book ("
      "book_id INTEGER PRIMARY KEY, "
      "title VARCHAR(200) NOT NULL, "
      "pages INTEGER NOT NULL)");

  // Build and execute the query: select all books ordered by pages descending
  auto query = select_from<Book>() 
             | order_by("pages"_c.desc()) 
             | to<std::vector<Book>>;

  // Execute query and return results
  auto result = query(conn);

  if (result) {
    return std::move(*result);
  }

  // Return empty vector if query fails
  return std::vector<Book>{};
}

}  // namespace select_from_read_to_vector
```

