Here's the complete implementation:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace analyze_department_employees {

struct Department {
  sqlgen::PrimaryKey<int> department_id;
  std::string department_name;
  std::string location;
};

struct Employee {
  sqlgen::PrimaryKey<int> employee_id;
  int department_id;
  std::string first_name;
  std::string last_name;
  double salary;
};

struct JoinResult {
  std::optional<std::string> department_name;
  std::optional<std::string> first_name;
  std::optional<std::string> last_name;
  std::optional<double> salary;
};

struct JoinAnalysis {
  std::vector<JoinResult> inner_join_results;
  std::vector<JoinResult> left_join_results;
  std::vector<JoinResult> right_join_results;
  std::vector<JoinResult> full_join_results;
};

/**
 * analyze_department_employees
 * Provides data-join analysis between Department and Employee input collections by
 * creating temporary SQL tables, inserting the provided rows, and executing a
 * variety of join queries to produce join-output samples.
 * Returns: JoinAnalysis.
 */
JoinAnalysis analyze_department_employees_impl(const std::vector<Department>& depts, const std::vector<Employee>& emps) {
  using namespace sqlgen;

  // Connect to SQLite database
  auto db = sqlite::connect("test_db.sqlite");

  // Create tables
  db.create_table<Department>();
  db.create_table<Employee>();

  // Insert departments
  for (const auto& dept : depts) {
    db.insert(dept);
  }

  // Insert employees
  for (const auto& emp : emps) {
    db.insert(emp);
  }

  JoinAnalysis analysis;

  // INNER JOIN: Get employees with assigned departments
  {
    using namespace sqlgen::literals;
    auto query = select_from<Department, "d">("department_name"_c) |
                 inner_join<Employee, "e">("d.department_id"_c == "e.department_id"_c) |
                 to<JoinResult>;

    analysis.inner_join_results = db.select(query);
  }

  // LEFT JOIN: Include all employees (even without departments)
  {
    using namespace sqlgen::literals;
    auto query = select_from<Employee, "e">("first_name"_c, "last_name"_c, "salary"_c) |
                 left_join<Department, "d">("e.department_id"_c == "d.department_id"_c) |
                 to<JoinResult>;

    analysis.left_join_results = db.select(query);
  }

  // RIGHT JOIN: Include all departments (even without employees)
  {
    using namespace sqlgen::literals;
    auto query = select_from<Employee, "e">("first_name"_c, "last_name"_c, "salary"_c) |
                 right_join<Department, "d">("e.department_id"_c == "d.department_id"_c) |
                 to<JoinResult>;

    analysis.right_join_results = db.select(query);
  }

  // FULL JOIN: Include all employees and departments
  {
    using namespace sqlgen::literals;
    auto query = select_from<Department, "d">("department_name"_c) |
                 full_join<Employee, "e">("d.department_id"_c == "e.department_id"_c) |
                 to<JoinResult>;

    analysis.full_join_results = db.select(query);
  }

  return analysis;
}

}  // namespace analyze_department_employees
