  db.create_table<Department>();
  db.create_table<Employee>();

  // Insert departments
  for (const auto& dept : depts) {
    db.insert(dept);
  }

  // Insert employees
  for (const auto& emp : emps) {
    db.insert(emp);
  }

  JoinAnalysis analysis;

  // INNER JOIN: Get employees with assigned departments
  {
    using namespace sqlgen::literals;
    auto query = select_from<Department, "d">("department_name"_c) |
                 inner_join<Employee, "e">("d.department_id"_c == "e.department_id"_c) |
                 to<JoinResult>;

    analysis.inner_join_results = db.select(query);
  }

  // LEFT JOIN: Include all employees (even without departments)
  {
    using namespace sqlgen::literals;
    auto query = select_from<Employee, "e">("first_name"_c, "last_name"_c, "salary"_c) |
                 left_join<Department, "d">("e.department_id"_c == "d.department_id"_c) |
                 to<JoinResult>;

    analysis.left_join_results = db.select(query);
  }

  // RIGHT JOIN: Include all departments (even without employees)
  {
    using namespace sqlgen::literals;
    auto query = select_from<Employee, "e">("first_name"_c, "last_name"_c, "salary"_c) |
                 right_join<Department, "d">("e.department_id"_c == "d.department_id"_c) |
                 to<JoinResult>;

    analysis.right_join_results = db.select(query);
  }

  // FULL JOIN: Include all employees and departments
  {
    using namespace sqlgen::literals;
    auto query = select_from<Department, "d">("department_name"_c) |
                 full_join<Employee, "e">("d.department_id"_c == "e.department_id"_c) |
                 to<JoinResult>;

    analysis.full_join_results = db.select(query);
  }

  return analysis;
}

}  // namespace analyze_department_employees

