Looking at the requirements and the reference code, I need to:

1. Use `sqlgen::select_from` to create a query on the `Product` table
2. Use `avg()` aggregation function on the `price` field
3. Add `+ 10.0` to the result using the `+` operator
4. Convert the query to SQL string using `to_sql()`

Here's the complete file:

```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <string>

namespace aggregation_arithmetic {

struct Product {
  sqlgen::PrimaryKey<int> id;
  double price;
};

/**
 * This function demonstrates arithmetic on aggregations.
 * Returns: std::string.
 */
inline std::string aggregation_arithmetic() {
    using namespace sqlgen;

    // Construct a query selecting AVG(price) + 10.0 from Product
    auto query = select_from<Product>(avg(col<"price">) + 10.0);

    // Generate and return the SQL string
    return sqlite::to_sql(query);
}

}  // namespace aggregation_arithmetic
