```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace get_top_products {

struct Product {
  sqlgen::PrimaryKey<int> product_id;
  std::string product_name;
  std::string category;
  double price;
};

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Date sale_date;
};

struct TopProduct {
  int product_id;
  std::string product_name;
  std::string category;
  double total_sales;
};

/**
 * Description: This function retrieves the top products based on total sales.
 * Returns: std::vector<TopProduct>.
 */
std::vector<TopProduct> get_top_products(size_t limit_count = 10) {
  // Connect to the SQLite database
  sqlgen::sqlite::Connection conn("test_db.sqlite");

  // Define table aliases for Product and Sales
  sqlgen::Table<Product> p("Product", "p");
  sqlgen::Table<Sales> s("Sales", "s");

  // Build the query
  auto query = sqlgen::Select(
    p.product_id,
    p.product_name,
    p.category,
    sqlgen::Sum(p.price * s.quantity).As("total_sales")
  )
  .From(p)
  .InnerJoin(s).On(p.product_id == s.product_id)
  .GroupBy(p.product_id, p.product_name, p.category)
  .OrderBy(sqlgen::Desc("total_sales"))
  .Limit(limit_count);

  // Execute the query
  auto result = conn.Execute(query);

  // Parse results into TopProduct vector
  std::vector<TopProduct> top_products;

  while (result.Next()) {
    TopProduct tp;
    tp.product_id = result.Get<int>(0);
    tp.product_name = result.Get<std::string>(1);
    tp.category = result.Get<std::string>(2);
    tp.total_sales = result.Get<double>(3);

    top_products.push_back(tp);
  }

  return top_products;
}

}  // namespace get_top_products
