```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <vector>

namespace weekday_sales_analysis {

struct Sales {
  sqlgen::PrimaryKey<int> sale_id;
  int product_id;
  int quantity;
  sqlgen::Timestamp<"%Y-%m-%d %H:%M:%S"> sale_time;
};

struct WeekdayStats {
  int weekday;
  int total_quantity;
};

/**
 * Description: This function analyzes sales data to calculate total quantity sold for each weekday.
 * Returns: std::vector<WeekdayStats>.
 */
std::vector<WeekdayStats> weekday_sales_analysis() {
  using namespace sqlgen;

  // Connect to the SQLite database
  auto conn = sqlite::connect("test_db.sqlite");

  // Define column literals
  using namespace sqlgen::literals;

  // Query to extract weekday from sale_time, aggregate quantities by weekday
  auto query = conn
    .select(
      weekday("sale_time"_c) | as<"weekday">,
      sum("quantity"_c) | as<"total_quantity">
    )
    .from<Sales>()
    .group_by(weekday("sale_time"_c));

  // Execute query and collect results into a vector
  return query | to<WeekdayStats> | collect::vector;
}

}  // namespace weekday_sales_analysis
```

**Explanation:**

1. **Database Connection**: Uses `sqlite::connect("test_db.sqlite")` to connect to the SQLite database.

2. **Column Literals**: Uses the `""_c` literal operator to reference table columns by name (`"sale_time"_c` and `"quantity"_c`).

3. **Weekday Extraction**: Uses the `weekday()` function to extract the weekday from the `sale_time` column.

4. **Aggregation**: Uses `sum()` to calculate the total quantity for each weekday.

5. **Aliasing**: Uses the `|` operator with `as<"...">` to give meaningful names to the computed columns that match the `WeekdayStats` struct fields.

6. **Grouping**: Uses `group_by()` to group results by weekday.

7. **Type Conversion & Collection**: Uses `to<WeekdayStats>` to convert query results to the target struct type, then `collect::vector` to collect all results into a `std::vector<WeekdayStats>`.

