```cpp
#pragma once

#include <sqlgen.hpp>
#include <sqlgen/sqlite.hpp>
#include <sqlgen/transpilation/read_to_select_from.hpp>
#include <string>

namespace read_to_select_from_usage {

struct User {
  sqlgen::PrimaryKey<int> id;
  std::string name;
  int age;
};

/**
 * This function demonstrates using read_to_select_from.
 * Returns: std::string.
 */
inline std::string read_to_select_from_usage() {
  // Create a Read query for User with conditions
  using namespace sqlgen::literals;

  // Build the query: select from User where age > 18 limit 10
  auto query = sqlgen::Read<std::vector<User>>{}
             | sqlgen::where("age"_c > 18)
             | sqlgen::limit(10);

  // Use read_to_select_from to generate the SQL string
  auto sql_string = sqlgen::transpilation::read_to_select_from<sqlgen::sqlite::Dialect>(query);

  return sql_string;
}

}  // namespace read_to_select_from_usage
```

**Explanation:**

1. **Define User struct**: Already provided in the template with `id`, `name`, and `age` fields.

2. **Create the query**: 
   - Start with `sqlgen::Read<std::vector<User>>{}` to create a read query for a vector of User objects
   - Use the pipe operator `|` with `sqlgen::where("age"_c > 18)` to add the WHERE condition (using the `_c` literal to create a column reference)
   - Chain with `| sqlgen::limit(10)` to add the LIMIT clause

3. **Generate SQL**: 
   - Call `sqlgen::transpilation::read_to_select_from<sqlgen::sqlite::Dialect>(query)` to transpile the query object into an SQL string
   - The template parameter specifies SQLite dialect

4. **Return**: The generated SQL string is returned.

This will generate a SQL SELECT statement like: `SELECT id, name, age FROM User WHERE age > 18 LIMIT 10`

